import{_ as s,a0 as i,w as l,s as p,ao as d,I as r,x as t,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"5 种预防开源许可违规的方法 | LCTT x X-CMD","titleTemplate":false,"description":"5 种预防开源许可违规的方法 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 种预防开源许可违规的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 种预防开源许可违规的方法 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20220819 5 Ways To Prevent Open Source Licensing Violations","title":"5 种预防开源许可违规的方法","tag":"202306","desc":""},"relativePath":"202306/20220819 5 Ways To Prevent Open Source Licensing Violations.md","filePath":"[post].md"}'),m={name:"202306/20220819 5 Ways To Prevent Open Source Licensing Violations.md"};function u(f,e,h,T,_,x){const a=i("Link");return l(),p("div",null,[e[13]||(e[13]=d('<h1 id="_5-种预防开源许可违规的方法" tabindex="-1">5 种预防开源许可违规的方法 <a class="header-anchor" href="#_5-种预防开源许可违规的方法" aria-label="Permalink to “5 种预防开源许可违规的方法”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/26/182415zqdgqmmwlt2qn7zu.jpg" alt=""></p><p>开发人员可以通过将开源软件集成到其代码库中，节省时间并避免重复发明轮子。然而，这也带来了严重的许可侵权风险。你必须遵守适用于重新使用的开源代码的众多开源许可证之一。如果你不这样做，你（或你所在公司）有可能因违反开源许可证条款而被起诉。即使这种诉讼并不普遍发生，它们确实存在。实际上，考虑到现在许多开源项目由希望保护其在开源社区中的投资的企业运营，这种情况在未来可能更加频繁发生。</p><h3 id="_1、熟悉开源许可证" tabindex="-1">1、熟悉开源许可证 <a class="header-anchor" href="#_1、熟悉开源许可证" aria-label="Permalink to “1、熟悉开源许可证”">​</a></h3><p>了解开源许可证是防止开源许可侵权问题中最重要的一步。很容易认为所有开源许可证都施加相同的条件，或者它们都基本要求源代码的持续可用性。实际上，有数十种不同的开源许可证，它们都有着非常不同的条款。简单地认为只要你从一个开源项目获取代码，你可以随意使用它并保持源代码可访问，这是一个严重的错误。几个开源许可证的一个典型但经常被忽视的条件可能是需要向原始作者提供致谢。</p><h3 id="_2、记录你使用的开源内容" tabindex="-1">2、记录你使用的开源内容 <a class="header-anchor" href="#_2、记录你使用的开源内容" aria-label="Permalink to “2、记录你使用的开源内容”">​</a></h3><p>建立一个标准化的方法来记录你使用开源代码的情况是一个优秀的做法。导入模块或从 GitHub 粘贴代码并不难。但如果你不追踪代码来自何处以及使用了何种许可证，你可能会忘记在代码库中如何以及在哪里集成开源内容。此外，如果你在借用代码时无法证明自己遵守了有效的许可条件，那么在开源许可证发生变化时可能会产生问题。考虑在文档维基（如果有的话）中添加一个页面，列出你使用的开源代码，以避免出现这个问题。每当你包含开源组件或依赖时，至少在你自己的源代码中添加注释。</p><h3 id="_3、避免使用未经授权的开源组件" tabindex="-1">3、避免使用未经授权的开源组件 <a class="header-anchor" href="#_3、避免使用未经授权的开源组件" aria-label="Permalink to “3、避免使用未经授权的开源组件”">​</a></h3><p>有时，你可能会偶然发现一个隐藏的 GitHub 存储库或其他源代码托管位置，其中包含你希望使用的代码，但没有提到任何许可指南。你可能会认为代码的创建者希望让其成为开源代码，并且你可以根据自己的意愿使用它。但这是一个危险的假设。开发人员可能会后续对代码设置特定的许可条件，并要求你遵守这些条件，这可能导致未来产生许可侵权的指控。除非你有非常充分的理由，否则避免使用缺乏明确许可限制的模糊代码。</p><h3 id="_4、创建自己的开源代码" tabindex="-1">4、创建自己的开源代码 <a class="header-anchor" href="#_4、创建自己的开源代码" aria-label="Permalink to “4、创建自己的开源代码”">​</a></h3><p>将你自己的软件完全开源是减少与开源许可相关风险的一种方法。这意味着你将自动遵守任何要求保留派生源代码的开源许可条件。然而，请记住，仅仅开放你自己的代码并不能确保完全遵守许可证。你仍然需要努力确保你遵守每个许可证的规定，因为适用于你借用的代码的许可证可能与你选择的开源许可证不同。然而，你无需担心与源代码共享相关的任何条款。</p><h3 id="_5、自动检测开源组件" tabindex="-1">5、自动检测开源组件 <a class="header-anchor" href="#_5、自动检测开源组件" aria-label="Permalink to “5、自动检测开源组件”">​</a></h3><p>虽然在代码库内手动跟踪你如何使用开源是很好的做法，但通过使用能够自动识别开源组件和依赖项的软件，你可以降低出错的可能性。在这里，我们应该考虑两种不同类型的工具。一种是源代码组成分析（SCA）软件，它会自动扫描源代码并识别从值得信任的外部来源获取的元素。另一种是软件供应链管理解决方案，除其他功能外，还支持查找和监控应用程序堆栈中的任何开源依赖项。</p><p><em>（题图：MJ/2168d466-cfc3-47de-a8a5-fc7ebaaa445f）</em></p><hr>',15)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),n(a,{href:"https://www.opensourceforu.com/2022/08/5-ways-to-prevent-open-source-licensing-violations/"},{default:o(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/08/5-ways-to-prevent-open-source-licensing-violations/",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=t("作者：",-1)),n(a,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:o(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[6]||(e[6]=t(" 选题：",-1)),n(a,{href:"https://github.com/lkxed"},{default:o(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[7]||(e[7]=t(" 译者：ChatGPT 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const w=s(m,[["render",u]]);export{C as __pageData,w as default};
